<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Utensils, House, NotebookPen, MessageCircle, ChartNoAxesCombined, UserRound, Plus, RefreshCw, ChevronRight, Check, X, LogOut, Leaf, Clock, Wallet, ArrowUpRight, Download, Trash2, ShieldCheck } from 'lucide-vue-next'
import { useSession } from './store'
import NutritionSource from './NutritionSource.vue'
import ChatPanel from './ChatPanel.vue'
import KnowledgePanel from './KnowledgePanel.vue'
const browserWindow=window
const session=useSession(),route=useRoute(),router=useRouter()
const busy=ref(false),booting=ref(true),error=ref(''),notice=ref(''),authMode=ref('login'),email=ref(''),password=ref('')
const date=ref(''),profile=ref<any>(null),target=ref<any>(null),restricted=ref(false),plan=ref<any>(null),history=ref<any[]>([]),logs=ref<any[]>([]),foods=ref<any[]>([]),summary=ref<any>(null),proposals=ref<any[]>([]),feedback=ref<any>(null),trends=ref<any[]>([]),weights=ref<any[]>([])
const dirty=ref(false),setupStep=ref(1),allergenText=ref(''),exclusionText=ref(''),search=ref(''),showLog=ref(false),editing=ref<number|null>(null),message=ref(''),share=ref(false),answer=ref<any>(null),weightValue=ref<number|null>(null),deleteText=ref(''),mode=ref('demo')
const targetLower=ref(1800),targetUpper=ref(2200),targetPreview=ref<any>(null),historySelection=ref(''),customName=ref('')
const form=ref<any>({meal:'午餐',time:'12:00',status:'confirmed',finished:'yes',note:'',items:[]})
const meals=['早餐','午餐','晚餐']
const page=computed(()=>String(route.params.page||'today'))
const links=[{key:'today',label:'今日',icon:House},{key:'records',label:'记录',icon:NotebookPen},{key:'assistant',label:'助手',icon:MessageCircle},{key:'trends',label:'趋势',icon:ChartNoAxesCombined},{key:'profile',label:'我的',icon:UserRound}]
const filteredFoods=computed(()=>foods.value.filter(f=>f.name.includes(search.value)).slice(0,12))
const viewedPlan=computed(()=>historySelection.value?history.value.find(p=>String(p.id)===historySelection.value):plan.value)
const heading=computed(()=>({today:'好好吃饭，从这一餐开始。',plans:'把下一餐，安排得刚刚好。',records:'记下实际吃的每一餐。',assistant:'一起想想，下一餐怎么吃。',trends:'看见记录，慢慢找到节奏。',profile:'让建议更贴近你的生活。'}[page.value]||'好好吃饭，从这一餐开始。'))
const prettyDate=computed(()=>date.value?new Date(date.value+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}):'')
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function loadProfile(){const r=await session.api('/profile');profile.value=r.profile;session.revision=r.revision;restricted.value=r.restricted;target.value=r.target;if(!date.value)date.value=r.today;allergenText.value=r.profile.allergens.join('，');exclusionText.value=r.profile.exclusions.join('，');dirty.value=false}
async function loadDay(){
  if(!date.value)return
  const d=encodeURIComponent(date.value)
  const [p,l,s,a,t,w]=await Promise.all([session.api('/plans?date='+d),session.api('/food-logs?date='+d),session.api('/daily-summary?date='+d),session.api('/adjustments?date='+d),session.api('/trends?date='+d),session.api('/weight-logs')])
  plan.value=p.active;history.value=p.history;logs.value=l;summary.value=s;proposals.value=a;trends.value=t;weights.value=w;session.revision=s.data_revision;feedback.value=null;answer.value=null;historySelection.value=''
}
async function refresh(){await loadProfile();await loadDay()}
async function signIn(){await run(async()=>{const r=await session.api('/auth/'+(authMode.value==='register'?'register':'login'),'POST',{email:email.value,password:password.value});session.csrf=r.csrf;await session.restore();password.value='';await refresh();foods.value=await session.api('/foods?limit=100');await router.push(profile.value.goal_confirmed?'/today':'/profile')})}
async function saveProfile(){await run(async()=>{for(const key of ['age','height_cm','weight_kg','budget']){if(profile.value[key]==='')profile.value[key]=null};profile.value.allergens=allergenText.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean);profile.value.exclusions=exclusionText.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean);await session.api('/profile','PATCH',{revision:session.revision,profile:profile.value});await refresh();notice.value='档案已保存';if(profile.value.goal_confirmed)await router.push('/today')})}
async function generate(){await run(async()=>{await session.api('/plans/generate','POST',{date:date.value,revision:session.revision});await loadDay();notice.value='草案已生成，确认后才会生效'})}
async function replaceMeal(meal:string,old?:number,newFood?:number){await run(async()=>{await session.api('/adjustments/propose','POST',{date:date.value,revision:session.revision,meal,replace_food_id:old??null,food_id:newFood??null});await loadDay();notice.value='替换草案已生成，请查看修改前后'})}
async function decide(p:any,confirm:boolean){await run(async()=>{await session.api(`/adjustments/${p.id}/${confirm?'confirm':'reject'}`,'POST');await loadDay();notice.value=confirm?'新计划已生效':'草案已拒绝，计划未更改'})}
function openLog(meal='午餐',items:any[]=[],existing?:any){
  editing.value=existing?.id??null
  form.value={date:existing?.date??date.value,meal,time:existing?new Intl.DateTimeFormat('en-GB',{timeZone:profile.value.timezone,hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(existing.eaten_at)):(meal==='早餐'?'08:00':meal==='晚餐'?'18:30':'12:00'),status:existing?.status??'confirmed',finished:existing?.finished??'yes',note:existing?.note??'',items:items.map(i=>({food_id:i.food_id??null,name:i.name,grams:i.grams,state:i.state}))}
  search.value='';customName.value='';showLog.value=true
}
function zonedISO(day:string,time:string,zone:string){
  const desired=new Date(`${day}T${time}:00Z`).getTime();let guess=desired
  for(let i=0;i<3;i++){
    const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess))
    const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));const actual=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)
    guess+=desired-actual
  }
  return new Date(guess).toISOString()
}
async function saveLog(){await run(async()=>{
  const payload={revision:session.revision,eaten_at:zonedISO(form.value.date,form.value.time,profile.value.timezone),meal:form.value.meal,status:form.value.status,finished:form.value.finished,note:form.value.note,items:form.value.items.map((i:any)=>({food_id:i.food_id,name:i.name,grams:i.grams===''?null:i.grams}))}
  await session.api('/food-logs'+(editing.value?'/'+editing.value:''),editing.value?'PATCH':'POST',payload);showLog.value=false;await loadDay();notice.value='实际饮食记录已保存'
})}
async function deleteLog(id:number){if(!window.confirm('删除这条饮食记录？汇总会随之重新计算。'))return;await run(async()=>{await session.api(`/food-logs/${id}?revision=${session.revision}`,'DELETE');await loadDay();notice.value='记录已删除'})}
async function getFeedback(){await run(async()=>{feedback.value=await session.api('/feedback/generate','POST',{date:date.value})})}
async function ask(text?:string){if(text)message.value=text;if(!message.value.trim())return;await run(async()=>{answer.value=await session.api('/assistant/messages','POST',{date:date.value,message:message.value,share_context:share.value});proposals.value=await session.api('/adjustments?date='+date.value)})}
async function saveWeight(){await run(async()=>{await session.api('/weight-logs','POST',{date:date.value,revision:session.revision,kg:weightValue.value});await loadDay();notice.value='体重已记录；单日波动不会修改目标'})}
async function previewTarget(){await run(async()=>{targetPreview.value=await session.api('/targets/preview','POST',{revision:session.revision,lower:targetLower.value,upper:targetUpper.value})})}
async function confirmTarget(){await run(async()=>{await session.api('/targets/confirm','POST',{revision:session.revision,lower:targetPreview.value.lower,upper:targetPreview.value.upper,confirmed:true});targetPreview.value=null;await loadProfile();notice.value='手动目标已保存'})}
async function exportData(){await run(async()=>{const data=await session.api('/account/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='三餐有数-个人数据.json';a.click();URL.revokeObjectURL(url);notice.value='数据已导出'})}
async function removeAccount(){await run(async()=>{await session.api(`/account?revision=${session.revision}&confirm=${deleteText.value}`,'DELETE');session.loggedIn=false;profile.value=null;session.csrf='';date.value='';notice.value='账号及当前数据库中的关联数据已删除'})}
async function logout(){await run(async()=>{await session.api('/auth/logout','POST');session.loggedIn=false;session.csrf='';profile.value=null;date.value=''})}
function navigate(path:string){if(dirty.value&&!window.confirm('档案尚未保存，离开将丢失修改。继续？'))return;if(dirty.value){dirty.value=false;void run(loadProfile)};void router.push(path)}
function guardUnload(e:BeforeUnloadEvent){if(dirty.value||showLog.value){e.preventDefault();e.returnValue=''}}
function hasEaten(meal:string){return logs.value.some(x=>x.meal===meal&&x.status==='confirmed')}
function mealItems(meal:string){return viewedPlan.value?.items.filter((i:any)=>i.meal===meal)??[]}
function portions(item:any){const ps=foods.value.find(f=>f.id===item.food_id)?.portions;const p=ps?.find((x:any)=>x.unit!=='100克可食部')??ps?.[0];return p&&p.unit!=='100克可食部'?`约 ${(item.grams/p.grams).toFixed(1)} ${p.unit}`:'按可食部称重'}
function changedItems(p:any){return p.items.filter((i:any)=>!p.before?.items.some((b:any)=>b.meal===i.meal&&b.food_id===i.food_id&&b.grams===i.grams))}
watch(date,async(n,o)=>{if(o&&n&&session.loggedIn)await run(loadDay)})
onMounted(async()=>{window.addEventListener('beforeunload',guardUnload);try{mode.value=(await session.api('/health')).mode;await session.restore();await refresh();foods.value=await session.api('/foods?limit=100')}catch(e:any){if(session.loggedIn)error.value=e.message}finally{booting.value=false}})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',guardUnload))
</script>

<template>
  <div v-if="booting" class="loading-screen"><Utensils :size="32"/><p>正在打开你的饮食手账…</p></div>
  <div v-else-if="!session.loggedIn" class="auth-layout">
    <section class="auth-story"><div class="brand"><Utensils/><strong>三餐有数</strong></div><div><h1>认真吃饭，<br>不用算得很累。</h1><p>从可执行的三餐开始。<br>记录真实饮食，把调整留给下一餐。</p><div class="plate large" aria-hidden="true"><i></i><i></i><i></i></div></div><small>你的健康饮食手账与助手</small></section>
    <main class="auth-form"><span class="tag">{{ mode==='live'?'模型模式 · 可追溯营养参考':'演示模式 · 无需模型密钥' }}</span><h2>{{ authMode==='login'?'欢迎回来':'开始你的饮食手账' }}</h2><p class="muted">同一个账号，在手机和电脑接着记录。</p><form @submit.prevent="signIn"><label>邮箱<input v-model="email" type="email" autocomplete="username" required placeholder="you@example.com"></label><label>密码<input v-model="password" type="password" :autocomplete="authMode==='login'?'current-password':'new-password'" required minlength="10" maxlength="128" placeholder="至少 10 位字符"></label><p class="privacy">档案和饮食记录用于生成计划与反馈，存储在此应用后端。真实模型调用需单次授权；你可以导出或删除账号数据。</p><button class="primary full" :disabled="busy">{{ busy?'正在处理…':authMode==='login'?'登录':'注册并开始' }}</button></form><button class="text-button" @click="authMode=authMode==='login'?'register':'login'">{{ authMode==='login'?'还没有账号？注册':'已有账号？登录' }}</button><p v-if="error" role="alert" class="error">{{ error }}</p></main>
  </div>
  <div v-else class="app-shell">
    <aside class="sidebar"><button class="brand" @click="navigate('/today')"><Utensils/><strong>三餐有数</strong></button><p class="brand-note">让每一餐有着落</p><nav aria-label="主导航"><button v-for="item in links" :key="item.key" :class="{active:page===item.key||(item.key==='today'&&page==='plans')}" @click="navigate('/'+item.key)"><component :is="item.icon" :size="21"/><span>{{ item.label }}</span></button></nav><div class="sidebar-foot"><Leaf :size="22"/><p>慢慢来，<br>每一餐都是新开始。</p><span class="tag">{{ mode==='live'?'LangChain 模型模式':'LangChain 演示模式' }}</span><small>USDA 参考数据 · 旧记录保留原来源</small></div></aside>
    <main class="main-content">
      <header class="topbar"><span>饮食手账 <ChevronRight :size="14"/> {{ links.find(x=>x.key===page)?.label||'计划' }}</span><button class="icon-button" title="刷新服务器数据" aria-label="刷新服务器数据" :disabled="busy" @click="run(refresh)"><RefreshCw :size="18"/></button><span class="avatar">{{ session.email[0]?.toUpperCase() }}</span></header>
      <section class="page-heading"><div><p class="date-caption">{{ prettyDate }}</p><h1>{{ heading }}</h1><p class="muted">{{ page==='today'?'计划是参考，实际吃了什么，由你来记录。':'所有记录保存在后端，同一账号刷新即可同步。' }}</p></div><label v-if="page!=='profile'" class="date-picker">查看日期<input type="date" v-model="date" :disabled="busy||showLog"></label></section>
      <div v-if="busy" class="progress" role="status">正在处理，请稍候…</div>
      <div v-if="error" role="alert" class="error">{{ error }} <button @click="run(refresh)" :disabled="busy">刷新数据</button></div>
      <div v-if="notice" role="status" class="notice"><Check :size="17"/>{{ notice }}</div>
      <div v-if="profile&&!profile.goal_confirmed&&page!=='profile'" class="banner">先完善档案并确认目标，就能生成第一份计划。<button @click="navigate('/profile')">设置档案</button></div>

      <template v-if="page==='today'||page==='plans'">
        <div class="overview-strip"><div><span class="stat-label">已知实际摄入</span><strong>{{ summary?.actual.known.kcal??0 }} <small>kcal</small></strong><span>{{ summary?.confirmed_count??0 }} 条已确认记录，非全天完整总量</span></div><div><span class="stat-label">蛋白质 / 碳水 / 脂肪</span><strong class="macro">{{ summary?.actual.known.protein??0 }} / {{ summary?.actual.known.carbs??0 }} / {{ summary?.actual.known.fat??0 }} <small>g</small></strong><span>按食物来源估算，不作为精确处方</span></div><div><span class="stat-label">待完善</span><strong>{{ summary?.pending_count??0 }} <small>条记录</small></strong><span>{{ summary?.actual.complete?'已确认项暂无未知营养':'存在未知营养，仅显示已知部分' }}</span></div></div>
        <section class="section-head"><div><h2>三餐计划 <span class="pill">{{ plan?'生效 v'+plan.version:'尚未建立' }}</span></h2><p class="muted">{{ profile?.dining }}场景 · {{ profile?.budget!=null?'每日预算 ¥'+profile.budget:'未设置预算' }} · 价格与供应请自行核对</p></div><button class="primary" :disabled="busy" @click="generate"><Plus :size="18"/>生成计划草案</button></section>
        <div v-if="history.length>1" class="history-select"><label>查看历史版本<select v-model="historySelection"><option value="">当前生效版本</option><option v-for="p in history" :value="String(p.id)">v{{ p.version }} · {{ p.id===plan?.id?'当前':'历史快照' }}</option></select></label></div>
        <div v-if="!viewedPlan" class="empty-plan"><div class="plate" aria-hidden="true"><i></i><i></i><i></i></div><div><h3>为今天留一点吃饭的余地</h3><p>生成三餐结构示例，查看食物和份量，<br>确认后才会成为今天的计划。</p><small>不使用未经核验的热量公式</small></div></div>
        <div v-else class="meal-grid"><article v-for="(meal,index) in [...meals,...(viewedPlan.items.some((i:any)=>i.meal==='加餐')?['加餐']:[])]" class="meal-card" :key="meal"><div class="meal-header"><span>{{ ['08:00','12:00','18:30','按需'][index] }} · 示例时间</span><span v-if="hasEaten(meal)" class="eaten"><Check :size="14"/>已记录</span></div><div class="meal-title"><h3>{{ meal }}</h3><div class="mini-plate" :class="'meal-'+index" aria-hidden="true"></div></div><ul class="food-list"><li v-for="item in mealItems(meal)"><div><strong>{{ item.name }}</strong><small>{{ item.state }} · {{ portions(item) }}</small></div><span>{{ item.grams }}g</span></li></ul><p class="meal-hint">{{ profile?.dining==='做饭'?'蒸煮优先，调味与用油需另行记录。':'按食物类别找相近餐食，实际份量以记录为准。' }}</p><details class="meal-detail"><summary>营养估算与可替换食物</summary><div v-for="i in mealItems(meal)" class="detail-item"><strong>{{ i.name }}</strong><small>{{ i.nutrients.kcal??'未知' }} kcal · 蛋白 {{ i.nutrients.protein??'未知' }}g · 碳水 {{ i.nutrients.carbs??'未知' }}g · 脂肪 {{ i.nutrients.fat??'未知' }}g</small><NutritionSource :item="i"/><select aria-label="选择替换食物" :disabled="busy||hasEaten(meal)||!!historySelection" @change="replaceMeal(meal,i.food_id,Number(($event.target as HTMLSelectElement).value));($event.target as HTMLSelectElement).value='' "><option value="">选择食物并生成替换草案</option><option v-for="f in foods.filter(f=>f.group===i.group&&f.id!==i.food_id)" :value="f.id">{{ f.name }} · {{ f.state }}</option></select></div></details><div class="meal-actions"><button :disabled="busy||hasEaten(meal)||!!historySelection" @click="replaceMeal(meal)"><RefreshCw :size="15"/>换一种</button><button :disabled="busy||!!historySelection" @click="openLog(meal,mealItems(meal))">记录实际吃的<ChevronRight :size="15"/></button></div></article></div>
        <div class="today-bottom"><section class="journal"><div class="section-head"><h2>实际饮食</h2><button class="text-button" @click="openLog()"><Plus :size="16"/>添加记录</button></div><div v-if="!logs.length" class="empty-inline"><NotebookPen :size="26"/><p>还没有饮食记录。<br><small>计划中的食物不会自动计入摄入。</small></p></div><div v-for="log in logs" class="journal-row"><span class="meal-dot"></span><div><strong>{{ log.meal }}</strong><p>{{ log.items.map((x:any)=>x.name).join('、') }}</p></div><span class="pill">{{ log.status==='confirmed'?'已确认':'待确认' }}</span><button class="text-button" @click="openLog(log.meal,log.items,log)">编辑</button></div></section><section class="feedback-panel"><Leaf :size="24"/><h2>下一餐，轻松一点</h2><p>记录完整，建议才更有依据。<br>不用因为一餐偏差打乱正常进餐。</p><button :disabled="busy" @click="getFeedback">查看今日反馈 <ArrowUpRight :size="17"/></button></section></div>
        <section v-if="feedback" class="response-panel"><h3>{{ feedback.summary }}</h3><h4>已知事实</h4><p v-for="t in feedback.known_facts">{{ t }}</p><h4>估算与不确定项</h4><p v-for="t in feedback.uncertainties">{{ t }}</p><h4>下一步建议</h4><p v-for="t in feedback.suggestions">{{ t }}</p></section>
      </template>

      <template v-if="page==='records'"><section class="section-head"><div><h2>当天饮食账本</h2><p class="muted">补录请切换上方日期。未确认项不计入营养汇总。</p></div><button class="primary" @click="openLog()"><Plus :size="18"/>添加记录</button></section><div v-if="!logs.length" class="empty-inline spacious"><NotebookPen/><p>从最近吃的一餐开始记录。</p></div><article v-for="log in logs" class="record-card"><div class="section-head"><h3>{{ log.meal }} <span class="pill">{{ log.status==='confirmed'?'已确认':'待确认' }}</span></h3><span>{{ new Date(log.eaten_at).toLocaleTimeString('zh-CN',{timeZone:profile.timezone,hour:'2-digit',minute:'2-digit'}) }}</span></div><ul class="food-list"><li v-for="i in log.items"><div><strong>{{ i.name }} · {{ i.grams??'待填写' }}g</strong><small>{{ i.state }} · {{ i.source }}</small><details><summary>营养与来源</summary><NutritionSource :item="i"/></details></div><span>{{ i.nutrients.kcal??'未知' }} kcal</span></li></ul><p v-if="log.note">{{ log.note }}</p><div class="actions"><button @click="openLog(log.meal,log.items,log)">编辑 / 确认</button><button class="danger-text" :disabled="busy" @click="deleteLog(log.id)"><Trash2 :size="15"/>删除</button></div></article></template>

      <KnowledgePanel v-if="page==='assistant'&&profile"/>
      <ChatPanel v-if="page==='assistant'&&profile" :date="date" :timezone="profile.timezone" :mode="mode" @updated="run(loadDay)" @review-log="log=>openLog(log.meal,log.items,log)"/>

      <template v-if="page==='trends'"><section class="trend-panel"><h2>最近 7 天的记录</h2><p class="muted">只展示已知摄入，不代表全天总量。记录较少时，不判断饮食或体重趋势。</p><div class="chart" aria-label="七天已知能量柱状图"><div v-for="d in trends" class="chart-day"><span>{{ d.actual.known.kcal }}</span><div class="bar-track"><div class="bar" :style="{height:(d.confirmed_count?Math.max(3,d.actual.known.kcal/Math.max(1,...trends.map(t=>t.actual.known.kcal))*100):0)+'%'}"></div></div><small>{{ d.date.slice(5) }}</small><small>{{ d.recorded_meals.length }} 餐</small></div></div><p class="caption">单位 kcal · 0 餐表示没有已确认记录，不等于没有进食</p><details><summary>查看可访问数据表</summary><table><thead><tr><th>日期</th><th>已知 kcal</th><th>未知项</th><th>待确认</th></tr></thead><tbody><tr v-for="d in trends"><td>{{ d.date }}</td><td>{{ d.actual.known.kcal }}</td><td>{{ Math.max(...Object.values(d.actual.missing) as number[]) }}</td><td>{{ d.pending_count }}</td></tr></tbody></table></details></section><section class="record-card"><h2>自愿记录体重</h2><form class="inline-form" @submit.prevent="saveWeight"><label>体重（kg）<input v-model.number="weightValue" type="number" min="20" max="350" step="0.1" required></label><button :disabled="busy" class="primary">记录</button></form><p class="muted">体重会受多种因素影响，不因单日变化自动调整目标。</p><div v-for="w in weights" class="weight-row"><span>{{ w.date }}</span><strong>{{ w.kg }} kg</strong></div></section></template>

      <template v-if="page==='profile'&&profile"><section class="profile-panel"><div class="section-head"><h2>饮食档案</h2><span v-if="dirty" class="tag">有未保存修改</span><span v-else class="pill">已同步</span></div><div class="steps"><button v-for="(name,i) in ['基本信息','就餐与偏好','范围与目标']" :class="{selected:setupStep===i+1}" @click="setupStep=i+1">{{ i+1 }}. {{ name }}</button></div><form @submit.prevent="saveProfile" @input="dirty=true" @change="dirty=true"><div v-show="setupStep===1" class="form-grid"><label class="check-label wide"><input type="checkbox" v-model="profile.adult">我确认已满 18 周岁</label><label>年龄（可选）<input type="number" v-model.number="profile.age" min="1" max="120"></label><label>身高 cm（可选）<input type="number" v-model.number="profile.height_cm" min="80" max="250"></label><label>体重 kg（可选）<input type="number" v-model.number="profile.weight_kg" min="20" max="350" step="0.1"></label><label>时区<input v-model="profile.timezone" required placeholder="Asia/Shanghai"></label><label>工作活动量<select v-model="profile.activity"><option>久坐</option><option>轻活动</option><option>较活跃</option></select></label><label>运动频率和类型<input v-model="profile.exercise" maxlength="200" placeholder="例如：每周两次力量训练"></label><p class="muted wide">可部分填写；这些参数不会用于未经核验的热量公式，也不会重复计算运动消耗。</p></div><div v-show="setupStep===2" class="form-grid"><label>每日预算（元，可选）<input type="number" v-model.number="profile.budget" min="0" max="10000"></label><label>主要就餐方式<select v-model="profile.dining"><option>食堂</option><option>外卖</option><option>做饭</option></select></label><label>可用厨具<input v-model="profile.equipment" maxlength="200" placeholder="例如：电饭锅、微波炉"></label><label>备餐时间（分钟）<input type="number" v-model.number="profile.prep_minutes" min="0" max="300"></label><label>用餐时间<input v-model="profile.meal_times" maxlength="100"></label><label>饮食类型<select v-model="profile.diet"><option>无</option><option>纯素</option><option>蛋奶素</option></select></label><label class="wide">过敏原（逗号分隔）<input v-model="allergenText" placeholder="例如：乳、蛋、大豆、麸质、花生、坚果、鱼、甲壳类、芝麻"><small>没有过敏原可留空或填写“无”。无法识别的真实过敏原会阻止生成计划，不会默认安全。</small></label><label class="wide">忌口 / 宗教限制 / 不喜欢的食材<input v-model="exclusionText" placeholder="填写具体禁止食材，以逗号分隔，例如：牛肉、猪肉"><small>没有限制可留空或填写“无”。仅按明确食材匹配，不自动推断宗教规则。</small></label><label class="wide">口味偏好<input v-model="profile.preferences" maxlength="300" placeholder="例如：喜欢清淡，方便打包"></label></div><div v-show="setupStep===3" class="form-grid"><label>当前目标<select v-model="profile.goal"><option>均衡饮食</option><option>体重管理</option><option>增肌支持</option></select></label><label class="check-label"><input type="checkbox" v-model="profile.goal_confirmed">确认这个目标</label><fieldset class="wide"><legend>服务范围筛查（适用时勾选）</legend><label v-for="item in ['孕哺期','治疗性饮食','进食障碍相关']" class="check-label"><input type="checkbox" :value="item" v-model="profile.special">{{ item }}</label></fieldset><p class="banner wide">未成年、孕哺期、需要治疗性饮食或有进食障碍相关情况时，保留记录与一般结构示例，不生成个性化热量限制方案。个体方案请寻求专业支持。</p></div><div class="actions"><button type="button" v-if="setupStep>1" @click="setupStep--">上一步</button><button type="button" v-if="setupStep<3" class="primary" @click="setupStep++">下一步</button><button v-else class="primary" :disabled="busy">保存档案与目标</button></div></form></section><section class="record-card"><h2>手动营养目标（可选）</h2><p class="muted">{{ target?`当前手动目标：${target.lower}–${target.upper} kcal/日`:'未设置精确热量目标；仍可使用三餐结构计划。' }} 此处不提供自动公式或医学处方。</p><div v-if="!restricted" class="inline-form"><label>下限 kcal<input type="number" v-model.number="targetLower" min="1200" max="5000"></label><label>上限 kcal<input type="number" v-model.number="targetUpper" min="1200" max="5000"></label><button :disabled="busy" @click="previewTarget">预览目标</button></div><div v-if="targetPreview" class="banner">确认手动输入 {{ targetPreview.lower }}–{{ targetPreview.upper }} kcal/日？未经专业核验。<button :disabled="busy" @click="confirmTarget">确认保存</button></div></section><section class="record-card"><h2>账号与数据</h2><p>{{ session.email }}</p><p class="muted">数据仅保存在配置的后端数据库。删除会移除当前库中的账号、会话、档案、计划、草案、记录和反馈；不会清除你已导出的文件、数据库备份或模型服务商可能保留的内容。</p><div class="actions"><button :disabled="busy" @click="exportData"><Download :size="16"/>导出个人数据</button><button :disabled="busy" @click="logout"><LogOut :size="16"/>退出登录</button></div><details class="delete-zone"><summary>删除账号与关联数据</summary><label>输入 DELETE 确认不可恢复删除<input v-model="deleteText" autocomplete="off"></label><button class="danger" :disabled="busy||deleteText!=='DELETE'" @click="removeAccount">永久删除当前数据库中的账号数据</button></details></section></template>

      <section v-if="proposals.length&&['today','plans'].includes(page)" class="proposals"><div class="section-head"><h2>等待你确认 <span class="pill">{{ proposals.length }} 份草案</span></h2><span class="muted">确认前不更改生效计划</span></div><article v-for="p in proposals" class="proposal"><span class="tag">{{ p.base_plan_id?'调整预览':'新计划预览' }}</span><h3>{{ p.reason }}</h3><div class="proposal-compare"><div v-if="p.before"><h4>修改前 · v{{ p.before.version }}</h4><p v-for="m in [...meals,...(p.items.some((i:any)=>i.meal==='加餐')?['加餐']:[])]"><strong>{{ m }}</strong> {{ p.before.items.filter((i:any)=>i.meal===m).map((i:any)=>`${i.name} ${i.grams}g`).join('、') }}</p></div><div><h4>确认后 · 建议份量</h4><p v-for="m in [...meals,...(p.items.some((i:any)=>i.meal==='加餐')?['加餐']:[])]"><strong>{{ m }}</strong> {{ p.items.filter((i:any)=>i.meal===m).map((i:any)=>`${i.name} ${i.grams}g`).join('、') }}</p></div></div><p class="muted">已知计划能量约 {{ p.totals.known.kcal }} kcal；这是计划估算，不是实际摄入，也不是目标处方。</p><p v-if="p.base_data_revision!==session.revision" class="error">数据已变化，这份草案已过期。请拒绝后重新生成。</p><div class="actions"><button class="primary" :disabled="busy||p.base_data_revision!==session.revision" @click="decide(p,true)"><Check :size="16"/>确认应用</button><button :disabled="busy" @click="decide(p,false)">拒绝草案</button></div></article></section>
      <footer class="page-footer"><ShieldCheck :size="15"/>营养为参考估算 · 生熟及烹调方式须匹配 · 不替代专业诊疗</footer>
    </main>
    <nav class="bottom-nav" aria-label="手机导航"><button v-for="item in links" :class="{active:page===item.key}" @click="navigate('/'+item.key)"><component :is="item.icon" :size="21"/><span>{{ item.label }}</span></button></nav>
  </div>

  <div v-if="showLog" class="modal-backdrop" @click.self="!busy&&browserWindow.confirm('关闭并放弃未保存的记录？')&&(showLog=false)"><section class="log-modal" role="dialog" aria-modal="true" aria-labelledby="log-title"><div class="section-head"><h2 id="log-title">{{ editing?'编辑实际饮食':'记录实际吃的食物' }}</h2><button class="icon-button" aria-label="关闭记录窗口" :disabled="busy" @click="browserWindow.confirm('关闭并放弃未保存的记录？')&&(showLog=false)"><X/></button></div><p class="muted">{{ form.date }} · {{ profile?.timezone }}。份量填写实际吃下的可食部克数。</p><form @submit.prevent="saveLog"><div class="form-grid"><label>就餐日期<input type="date" v-model="form.date" required></label><label>餐次<select v-model="form.meal"><option v-for="m in [...meals,'加餐']">{{ m }}</option></select></label><label>用餐时间<input type="time" v-model="form.time" required></label></div><div class="search-food"><label>搜索食物<input v-model="search" placeholder="搜索食物名称，区分生重 / 熟重"></label><div class="food-results"><button v-for="f in filteredFoods" type="button" @click="form.items.push({food_id:f.id,name:f.name,grams:f.portions[0]?.grams??100,state:f.state})">{{ f.name }}<small>{{ f.state }} · {{ f.demo?'演示':'USDA' }}</small><Plus :size="14"/></button></div><div class="inline-form"><label>自定义食物（营养未知）<input v-model="customName" maxlength="100" placeholder="例如：食堂炒菜"></label><button type="button" :disabled="!customName.trim()" @click="form.items.push({food_id:null,name:customName,grams:null,state:'未知'});customName=''">添加</button></div></div><div v-if="!form.items.length" class="empty-inline">从上方选食物或添加自定义食物。</div><div v-for="(i,index) in form.items" class="log-item"><div><strong>{{ i.name }}</strong><small>{{ i.state }}</small></div><label>实际克数<input type="number" v-model.number="i.grams" min="1" max="3000" step="0.1" :required="form.status==='confirmed'"></label><button type="button" class="icon-button" aria-label="移除此食物" @click="form.items.splice(index,1)"><X :size="16"/></button></div><div class="form-grid"><label>是否吃完<select v-model="form.finished"><option value="yes">全部吃完</option><option value="partial">只吃部分（克数已扣除剩余）</option><option value="unknown">尚不确定</option></select></label><label>确认状态<select v-model="form.status"><option value="confirmed">确认后计入已知摄入</option><option value="pending">待完善，暂不计入</option></select></label><label class="wide">备注<input v-model="form.note" maxlength="500" placeholder="可选：饥饿感、精力或份量的不确定性"></label></div><p class="caption">自定义食物即使确认，营养仍标记未知，不会被当成零。</p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full" :disabled="busy||!form.items.length">{{ busy?'正在保存…':'保存实际记录' }}</button></form></section></div>
</template>



